import{_ as s,a0 as u,w as a,s as r,ao as d,I as i,x as n,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"每日Ubuntu小技巧：合上筆記本，系統不睡眠 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧：合上筆記本，系統不睡眠 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧：合上筆記本，系統不睡眠 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧：合上筆記本，系統不睡眠 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Daily Ubuntu Tips – Do Nothing When Laptop Lid Is Closed","title":"每日Ubuntu小技巧：合上筆記本，系統不睡眠","tag":"201401","desc":""},"relativePath":"201401/Daily Ubuntu Tips – Do Nothing When Laptop Lid Is Closed.md","filePath":"[post].md"}'),l={name:"201401/Daily Ubuntu Tips – Do Nothing When Laptop Lid Is Closed.md"};function g(b,t,T,m,f,C){const e=u("Link");return a(),r("div",null,[t[11]||(t[11]=d(`<h1 id="每日ubuntu小技巧-合上筆記本-系統不睡眠" tabindex="-1">每日Ubuntu小技巧：合上筆記本，系統不睡眠 <a class="header-anchor" href="#每日ubuntu小技巧-合上筆記本-系統不睡眠" aria-label="Permalink to “每日Ubuntu小技巧：合上筆記本，系統不睡眠”">​</a></h1><p>Ubuntu 是一個處在牛 A 和牛 C 之間的現代操作系統，全世界數百萬用户和公司都在使用它。無論是充當工作台還是高級工程機器，Ubuntu 都遊刃有餘。</p><p>如果你是 Ubuntu 初學者，使用過程還需要高手指導，那就關注本站吧。我們已經寫了數百篇 Ubuntu 教程，足以帶你入門。從安裝 Ubuntu 到系統基本設置，我們都有涉獵。</p><p>這篇簡單的教程為你介紹當筆記本蓋子合上時該幹嘛還是幹嘛，而不是進入睡眠模式或者直接關機。</p><p>大多數現代操作系統（包括 Windows）會在筆記本合上時進入睡眠狀態。Ubuntu 也是如此。如果你想讓你的筆記本蓋子合上時不睡眠，就跟着我們學習吧。</p><p>要達到這個目的，Ubuntu 有兩種方法。第一種是打開 <strong>System Settings –&gt; Power</strong>（中文版是打開 <strong>系統設置 -&gt; 電源</strong>），然後進行設置。一些用户設置後不會生效。</p><p>另一個方法是直接編輯 Login Manager 的配置文件（<strong>logind.conf</strong>）。這個方法基本能生效，建議使用這個。</p><p>要開始了，按下 <strong>Ctrl – Alt – T</strong> 組合鍵，打開終端。然後運行下面的命令打開 logind.conf 文件。你的所有修改都在這個文件內。</p><pre><code>sudo gedit /etc/systemd/logind.conf
</code></pre><p>打開文件後修改下面這行：</p><pre><code>#HandleLidSwitch=suspend
</code></pre><p>改成這樣：</p><pre><code>HandleLidSwitch=ignore
</code></pre><p>保存文件，重啓 Login Manager 服務：</p><pre><code>sudo restart systemd-logind
</code></pre><p>工作完成！</p><p>配置文件的 “ignore” 值告訴 Ubuntu 當筆記本合上後不要睡眠或掛起。不要改動其它設置然後保存文件。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/12/photo.jpg" alt=""></p><hr>`,19)),i("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-do-nothing-when-laptop-lid-is-closed/"},{default:p(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/12/daily-ubuntu-tips-do-nothing-when-laptop-lid-is-closed/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=n("譯者：",-1)),o(e,{href:"https://github.com/bazz2"},{default:p(()=>[...t[2]||(t[2]=[n("bazz2",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),o(e,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const h=s(l,[["render",g]]);export{U as __pageData,h as default};
